
// ---------------------------------------------------------------------------
// New LoveCount screens + page-level wiring.
// Markup re-uses the EXACT class vocabulary from the Stitch design system so
// each new page is visually indistinguishable from the originals.
// ---------------------------------------------------------------------------

const ICON = "data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'><defs><linearGradient id='g' x1='.08' y1='0' x2='.92' y2='1'><stop offset='0' stop-color='#FF9BC0'/><stop offset='.46' stop-color='#F43F7A'/><stop offset='1' stop-color='#B4144C'/></linearGradient><linearGradient id='h' x1='.2' y1='0' x2='.85' y2='1'><stop offset='0' stop-color='#FFFFFF'/><stop offset='.7' stop-color='#FFF6F9'/><stop offset='1' stop-color='#FFE1EB'/></linearGradient></defs><rect width='64' height='64' rx='14.5' fill='url(%23g)'/><g transform='scale(.125)'><circle cx='256' cy='246' r='168' fill='none' stroke='#FFFFFF' stroke-opacity='.2' stroke-width='13'/><path d='M256 78A168 168 0 0 1 424 246' fill='none' stroke='#FFFFFF' stroke-opacity='.62' stroke-width='13' stroke-linecap='round'/><circle cx='424' cy='246' r='14' fill='#FFFFFF' opacity='.95'/><path d='M256 432C249 425 100 334 100 220C100 152 150 104 210 104C240 104 253 117 256 127C259 117 272 104 302 104C362 104 412 152 412 220C412 334 263 425 256 432Z' fill='url(%23h)'/></g></svg>";
const AVATAR = "data:image/jpeg;base64,";

const header = (title, sub) =>
`<header class="fixed top-0 inset-x-0 z-50 pt-safe bg-[#FFFBF8]/80 backdrop-blur-xl shadow-[0_1px_8px_rgba(0,0,0,0.04)]"><div class="h-20 px-space-lg flex items-center justify-between"><div class="flex items-center gap-space-sm"><img alt="LoveCount App Icon" class="h-8 w-auto object-contain" src="${ICON}"/><div class="flex flex-col"><div class="flex items-center gap-space-2xs"><span class="font-label-sm text-label-sm text-bubble-rose uppercase tracking-wider">${sub}</span><span class="inline-block w-1.5 h-1.5 rounded-full bg-bubble-pink animate-pulse"></span></div><h1 class="font-headline-sm text-headline-sm text-on-surface leading-tight">${title}</h1></div></div><div class="flex items-center gap-space-sm"><div data-act="open-settings" class="relative flex items-center justify-center p-0.5 rounded-full bg-gradient-to-tr from-bubble-pink via-bubble-yellow to-bubble-blue"><img alt="Couple" data-lc-who="couple" class="w-8 h-8 rounded-full object-cover ring-2 ring-white" src="${AVATAR}"/></div></div></div></header>`;

const screen = (id, title, sub, body) =>
`<section id="screen-${id}" class="lt-screen">${header(title, sub)}<main class="flex-1 flex flex-col relative w-full pt-20 pb-28 px-margin-mobile bg-transparent">${body}</main></section>`;

const back = (to, label, icon) =>
`<div class="flex items-center justify-between px-space-xs pt-1"><button data-goto="${to}" aria-label="Go back" class="flex items-center justify-center w-11 h-11 rounded-full bg-white text-on-surface shadow-[0_4px_16px_-2px_rgba(30,34,51,0.06)] active:scale-95 transition-transform" type="button"><span class="material-symbols-outlined text-[20px]">arrow_back_ios_new</span></button><div class="flex items-center gap-1.5 px-space-md py-1 bg-subtle-lavender rounded-full shadow-sm"><span class="material-symbols-outlined text-bubble-rose text-[16px]" style="font-variation-settings:'FILL' 1;">${icon}</span><span class="font-label-md text-label-md text-secondary">${label}</span></div><div class="w-11"></div></div>`;

const card = (inner, extra) =>
`<div class="p-space-lg rounded-3xl bg-card-surface shadow-[0_8px_24px_-4px_rgba(30,34,51,0.05),0_2px_6px_-1px_rgba(30,34,51,0.02)] flex flex-col gap-space-sm ${extra || ""}">${inner}</div>`;

