// ---------------------------------------------------------------------------
// PAGE_JS - second runtime pass: page forms, legacy design tagging, search.
// ---------------------------------------------------------------------------
export const PAGE_JS = `
(function(){
  if (window.__LC_PAGES__) return; window.__LC_PAGES__ = true;
  var LC = window.LC || {};
  function $(s,r){ return (r||document).querySelector(s); }
  function $$(s,r){ return Array.prototype.slice.call((r||document).querySelectorAll(s)); }
  function pad(n){ return (n<10?'0':'')+n; }
  function esc(s){ s=String(s==null?'':s); var o=''; for(var i=0;i<s.length;i++){ var c=s.charAt(i); if(c==='&'){o+='&amp;';} else if(c==='<'){o+='&lt;';} else if(c==='>'){o+='&gt;';} else if(c==='"'){o+='&quot;';} else {o+=c;} } return o; }
  function st(){ return LC.state ? LC.state() : null; }
  function commit(){ if(LC.save){ LC.save(); } if(LC.renderAll){ LC.renderAll(); } }

  // ---- data-id aware navigation (base handler fires first, so re-enter) ----
  document.addEventListener('click', function(e){
    var t=e.target; if(!t || !t.closest) return;
    var g=t.closest('[data-goto][data-id]');
    if(!g) return;
    var S=st(); if(!S) return;
    var dest=g.getAttribute('data-goto'), id=g.getAttribute('data-id');
    if(dest==='event_detail') S.__eventId=id;
    if(dest==='moment_detail') S.__momentId=id;
    if(dest==='note_detail') S.__noteId=id;
    if(window.__ltGo) window.__ltGo(dest);
  }, true);

  // ---- tag the ORIGINAL design screens so the runtime can drive them ------
  function tagCare(){
    var root=document.getElementById('screen-care'); if(!root || root.__tagged) return; root.__tagged=true;
    var big=$('.font-headline-lg-mobile', root); if(big) big.id='care-day';
    var tiles=$$('.font-headline-md', root);
    if(tiles[0]) tiles[0].id='care-next';
    if(tiles[1]) tiles[1].id='care-mood';
  }
  function tagSettings(){
    var root=document.getElementById('screen-settings'); if(!root || root.__tagged) return; root.__tagged=true;
    var toggles=$$('span', root).filter(function(s){ return (s.className||'').indexOf('w-11 h-6 rounded-full')!==-1; });
    if(toggles[0]){ toggles[0].setAttribute('data-toggle','notifications'); }
    if(toggles[1]){ toggles[1].setAttribute('data-toggle','careLock'); }
    toggles.forEach(function(t){
      t.style.cursor='pointer';
      t.addEventListener('click', function(){
        var k=t.getAttribute('data-toggle'); var S=st(); if(!k||!S) return;
        S.settings[k]=!S.settings[k]; commit();
        if(LC.toast) LC.toast((S.settings[k]?'On: ':'Off: ')+k,'tune');
      });
    });
    var rows=$$('div.rounded-2xl', root);
    rows.forEach(function(r){
      var txt=(r.textContent||'');
      if(txt.indexOf('Daily Reminder Time')!==-1){
        var val=$('.font-body-sm', r); if(val){ val.id='settings-reminder-time'; }
        r.style.cursor='pointer';
        r.addEventListener('click', function(){
          if(LC.openSheet){}
          var S=st();
          LC.toast('Reminder set to '+S.settings.reminder,'schedule');
        });
      }
      if(txt.indexOf('Appearance')!==-1){ var v=$('.font-body-sm', r); if(v) v.id='settings-appearance'; }
      if(txt.indexOf('Language')!==-1){ var v2=$('.font-body-sm', r); if(v2) v2.id='settings-language'; }
      if(txt.indexOf('About LoveCount')!==-1){
        r.removeAttribute('data-goto'); r.setAttribute('data-goto','about'); r.style.cursor='pointer';
      }
    });
  }

  // ---- page forms --------------------------------------------------------
  document.addEventListener('click', function(e){
    var t=e.target; if(!t || !t.closest) return;
    var b=t.closest('[data-pg-save]');
    if(!b) return;
    var kind=b.getAttribute('data-pg-save'), S=st(); if(!S) return;
    e.preventDefault(); e.stopPropagation();

    if(kind==='event'){
      var title=($('#pg-e-title')||{}).value||''; var date=($('#pg-e-date')||{}).value||'';
      if(!title.trim()){ LC.toast('Add a title first','event'); return; }
      if(!date.trim()){ date=pad(10)+'-'+pad(19); }
      S.events.push({ id:'e'+Date.now(), title:title.trim(), date:date.trim(),
        kind:($('#pg-e-kind')||{}).value||'celebration', note:($('#pg-e-note')||{}).value||'' });
      commit(); LC.toast('Event saved','event_available'); window.__ltGo('events');
    }
    if(kind==='moment'){
      var mt=($('#pg-m-title')||{}).value||'A lovely moment';
      var d=new Date();
      S.moments.push({ id:'m'+Date.now(), title:mt.trim(), body:($('#pg-m-body')||{}).value||'',
        place:($('#pg-m-place')||{}).value||'', photo:window.__pgPhoto||'',
        when:d.getDate()+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getMonth()], photos:1 });
      window.__pgPhoto='';
      commit(); LC.toast('Memory saved','photo_library'); window.__ltGo('moments');
    }
    if(kind==='note'){
      var body=($('#pg-n-body')||{}).value||'';
      if(!body.trim()){ LC.toast('Write something first','edit_note'); return; }
      var mood='Sweet'; var on=$('#pg-n-moods .lc-chip.on'); if(on) mood=on.getAttribute('data-mood');
      S.notes.unshift({ id:'n'+Date.now(), from:($('#pg-n-from')||{}).value||'Israel', body:body.trim(), mood:mood, hearts:0, replies:[] });
      commit(); LC.toast('Note saved','chat_bubble'); window.__ltGo('notes');
    }
  }, true);

  // mood chips on the compose page
  document.addEventListener('click', function(e){
    var t=e.target; if(!t || !t.closest) return;
    var m=t.closest('#pg-n-moods .lc-chip'); if(!m) return;
    e.preventDefault();
    $$('#pg-n-moods .lc-chip').forEach(function(x){ x.className='lc-chip'; });
    m.className='lc-chip on';
  }, true);

  // photo picker on add_moment page
  document.addEventListener('click', function(e){
    var t=e.target; if(!t || !t.closest) return;
    var b=t.closest('#pg-m-photo'); if(!b) return;
    e.preventDefault();
    if(LC.native) LC.native('pickImage', {});
    window.__lcPickCb=function(dataUrl){ window.__pgPhoto=dataUrl; var th=$('#pg-m-thumb'); if(th) th.innerHTML='<img src="'+dataUrl+'" style="width:100%;border-radius:1rem;"/>'; };
  }, true);

  // ---- global search page ------------------------------------------------
  function renderSearch(){
    var q=$('#pg-search'); var res=$('#search-results'); if(!q||!res) return;
    var S=st(); if(!S) return;
    var scope='all'; var on=$('#pg-search-scope .lc-chip.on'); if(on) scope=on.getAttribute('data-scope');
    var v=q.value.trim().toLowerCase();
    var out=[];
    function add(kind, title, sub){
      out.push('<div class="lc-row"><span class="material-symbols-outlined">'+
        (kind==='events'?'event':(kind==='notes'?'chat_bubble':'photo_library'))+'</span><span>'+esc(title)+' <span style="color:#9CA3AF;font-weight:400;">'+(sub?'&bull; '+esc(sub):'')+'</span></span></div>');
    }
    if(scope==='all'||scope==='events') S.events.forEach(function(x){ if(!v||(x.title||'').toLowerCase().indexOf(v)!==-1) add('events',x.title,x.date); });
    if(scope==='all'||scope==='notes') S.notes.forEach(function(x){ if(!v||(x.body||'').toLowerCase().indexOf(v)!==-1) add('notes',x.body,x.from); });
    if(scope==='all'||scope==='moments') S.moments.forEach(function(x){ if(!v||(x.title||'').toLowerCase().indexOf(v)!==-1) add('moments',x.title,x.place); });
    if(!out.length){ out.push('<div class="lc-empty"><span class="material-symbols-outlined">search_off</span><strong>Nothing found</strong><p>Try another word</p></div>'); }
    res.innerHTML=out.slice(0,40).join('');
  }
  document.addEventListener('input', function(e){ if(e.target && e.target.id==='pg-search') renderSearch(); }, true);
  document.addEventListener('click', function(e){
    var t=e.target; if(!t || !t.closest) return;
    var c=t.closest('#pg-search-scope .lc-chip'); if(!c) return;
    e.preventDefault();
    $$('#pg-search-scope .lc-chip').forEach(function(x){ x.className='lc-chip'; });
    c.className='lc-chip on'; renderSearch();
  }, true);

  // ---- profile stats -----------------------------------------------------
  function renderProfile(){
    var box=$('#profile-stats'); if(!box) return;
    var S=st(); if(!S) return;
    var start=new Date('2025-08-10T00:00:00');
    var days=Math.round((new Date()-start)/86400000); if(days<0) days=0;
    function stat(icon, val, label, tone){
      return '<div class="flex items-center justify-between p-3.5 px-4 rounded-2xl bg-card-surface shadow-[0_8px_24px_-4px_rgba(30,34,51,0.05)]"><div class="flex items-center gap-3.5 min-w-0"><div class="flex items-center justify-center w-11 h-11 rounded-2xl bg-'+tone+'/15 text-'+tone+' shrink-0"><span class="material-symbols-outlined text-[22px]" style="font-variation-settings:\\'FILL\\' 1;">'+icon+'</span></div><div class="flex flex-col min-w-0"><span class="font-headline-sm text-headline-sm text-on-surface truncate">'+val+'</span><span class="font-body-sm text-body-sm text-text-muted truncate">'+label+'</span></div></div></div>';
    }
    box.innerHTML = stat('favorite', days+' days', 'Together since 10 August 2025', 'bubble-rose')
      + stat('cake', '19 October', 'Esther\u2019s birthday', 'bubble-pink')
      + stat('chat_bubble', S.notes.length+' notes', 'Love notes written', 'bubble-purple')
      + stat('photo_library', S.moments.length+' memories', 'Saved moments', 'bubble-blue')
      + stat('event', S.events.length+' events', 'Dates you are tracking', 'bubble-emerald');
  }

  function tick(){
    tagCare(); tagSettings(); renderSearch(); renderProfile();
  }
  if(document.readyState==='complete'||document.readyState==='interactive'){ setTimeout(tick, 900); }
  else { window.addEventListener('DOMContentLoaded', function(){ setTimeout(tick, 900); }); }
  window.addEventListener('load', function(){ setTimeout(tick, 400); });
})();
`;
